css:
/* Появление снизу по очереди.
   Скрытое состояние действует только под классом .reveal-on на <html> (его ставит строчка в <head>),
   поэтому без JS, в печати и у поисковых роботов всё видно сразу. */
:root {
  --reveal-dist: 24px;                         /* путь 16–32px: больше уже читается как слайд-шоу */
  --reveal-dur: 480ms;                         /* строгий стиль 360ms, премиальный 560ms */
  --reveal-ease: cubic-bezier(.05, .7, .1, 1); /* вход с торможением (MD3 emphasized decelerate) */
  --reveal-step: 70ms;                         /* шаг очереди 50–100ms */
  --reveal-max: 420ms;                         /* потолок задержки: вся очередь короче 0,5 с */
}

/* ждёт своей очереди */
.reveal-on [data-reveal]:not([data-reveal="in"]) {
  opacity: 0;
  transform: translate3d(0, var(--reveal-dist), 0);
}

/* появляется: переход к собственным значениям элемента, задержка по номеру в пачке */
.reveal-on [data-reveal="in"] {
  transition: opacity var(--reveal-dur) var(--reveal-ease), transform var(--reveal-dur) var(--reveal-ease);
  transition-delay: min(calc(var(--i, 0) * var(--reveal-step)), var(--reveal-max));
}

/* клавиатура: фокус не должен оказаться внутри невидимой карточки */
.reveal-on [data-reveal]:focus-within {
  opacity: 1;
  transform: none;
}

/* уменьшение движения (уровень «смягчить»): без сдвига и без очереди, короткое проявление 200ms */
@media (prefers-reduced-motion: reduce) {
  .reveal-on [data-reveal]:not([data-reveal="in"]) {
    transform: none;
  }
  .reveal-on [data-reveal="in"] {
    transition: opacity 200ms linear;
    transition-delay: 0s;
  }
}

@media print {
  .reveal-on [data-reveal] {
    opacity: 1 !important;
    transform: none !important;
  }
}

