// Появление снизу по очереди: без зависимостей, IntersectionObserver.
// Карточки, вошедшие в экран одновременно, образуют пачку: номер в пачке (--i) задаёт задержку.
(() => {
  const root = document.documentElement;
  window.__reveal = true; // сигнал строчке в <head>: скрипт жив, класс не снимать
  const items = document.querySelectorAll('[data-reveal]');
  if (!('IntersectionObserver' in window)) { root.classList.remove('reveal-on'); return; }

  // после появления убираем атрибут: у карточки снова работают её собственные hover-переходы без задержки
  const done = (el) => {
    if (el.getAttribute && el.getAttribute('data-reveal') === 'in') {
      el.removeAttribute('data-reveal');
      el.style.removeProperty('--i');
    }
  };
  document.addEventListener('transitionend', (e) => { if (e.propertyName === 'opacity') done(e.target); });

  const row = (r) => Math.round(r.top / 16); // карточки одного ряда — одна строка очереди
  const io = new IntersectionObserver((entries) => {
    entries
      .filter((e) => e.isIntersecting)
      .sort((a, b) => (row(a.boundingClientRect) - row(b.boundingClientRect)) || (a.boundingClientRect.left - b.boundingClientRect.left))
      .forEach((e, i) => {
        const el = e.target;
        io.unobserve(el); // один раз, без повтора при прокрутке назад
        el.style.setProperty('--i', i);
        el.setAttribute('data-reveal', 'in');
        setTimeout(() => done(el), 2000); // страховка, если transitionend не придёт
      });
  }, { threshold: 0.15 });

  items.forEach((el) => io.observe(el));
  window.__reveal = io; // подгруженные позже карточки: window.__reveal.observe(el)
})();

