// npm i gsap (3.12+) — ScrollTrigger входит в пакет (лицензия GSAP Standard: бесплатно, но не MIT). Без CDN.
// Скрытие ставит gsap.set, поэтому строчка в <head> и CSS скрытого состояния не нужны. Модуль грузится после первой отрисовки:
// в первом экране data-reveal не ставить, иначе карточки мигнут. Прячем только opacity: autoAlpha добавил бы visibility:hidden,
// и ссылки в карточке выпали бы из Tab, а текст — из поиска Ctrl+F и читалок экрана. Оставьте в CSS одну строку:
// [data-reveal]:focus-within { opacity: 1 !important; transform: none !important; }
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
gsap.registerPlugin(ScrollTrigger);

const mm = gsap.matchMedia();
mm.add({ motion: '(prefers-reduced-motion: no-preference)', reduced: '(prefers-reduced-motion: reduce)' }, ({ conditions }) => {
  const items = gsap.utils.toArray('[data-reveal]');
  const reduced = conditions.reduced;
  gsap.set(items, reduced ? { opacity: 0 } : { opacity: 0, y: 24 });
  ScrollTrigger.batch(items, {
    start: 'clamp(top 85%)', // clamp: карточки у самого низа страницы тоже появятся
    once: true,
    interval: 0.1,
    onEnter: (batch) => gsap.to(batch, reduced
      ? { opacity: 1, duration: 0.2, ease: 'none', overwrite: true }
      : { opacity: 1, y: 0, duration: 0.48, ease: 'expo.out', overwrite: true, clearProps: 'transform',
          stagger: (i) => Math.min(i * 0.07, 0.42) }), // шаг 70ms, потолок 420ms — как в CSS-версии
  });
}); // при смене настройки matchMedia сам откатывает gsap.set и триггеры
